import { ActionMetrics, SimResult, SimResultFilter } from '../../proto_utils/sim_result.js';

import { damageTakenBarScale } from './metrics_bar_helpers.js';
import { MetricsCombinedTooltipTable } from './metrics_combined_tooltip_table.js';
import { ColumnSortType, MetricsTable } from './metrics_table.js';
import { MetricsTotalBar } from './metrics_total_bar.js';
import { ResultComponent, ResultComponentConfig, SimResultData } from './result_component.js';

// Single combined damage-taken table (melee + spell) with Cataclysm-style clean
// columns; avoidance breakdowns (dodge/parry/block) live in hover tooltips.
export class DamageTakenMetricsTable extends MetricsTable<ActionMetrics> {
	private maxValue = 0;
	private totalValue = 0;

	constructor(config: ResultComponentConfig) {
		config.rootCssClass = 'dtps-metrics-root';

		config.resultsEmitter.on((_, resultData) => {
			const scale = resultData ? damageTakenBarScale(resultData) : { max: 0, total: 0 };
			this.maxValue = scale.max;
			this.totalValue = scale.total;
		});

		super(config, [
			MetricsTable.nameCellConfig((metric: ActionMetrics) => {
				return {
					name: metric.name,
					actionId: metric.actionId,
				};
			}),
			{
				name: 'Damage taken',
				tooltip: 'Total Damage Taken',
				headerCellClass: 'metrics-table-cell--primary-metric',
				columnClass: 'metrics-table-cell--primary-metric',
				getValue: (metric: ActionMetrics) => metric.damage,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => {
					cellElem.appendChild(
						MetricsTotalBar({
							spellSchool: metric.spellSchool,
							percentage: this.totalValue > 0 ? (metric.damage / this.totalValue) * 100 : 0,
							max: this.maxValue,
							total: metric.damage,
							value: metric.damage,
						}),
					);
				},
			},
			{
				name: 'Casts',
				tooltip: 'Attacks',
				getValue: (metric: ActionMetrics) => metric.casts,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => {
					cellElem.textContent = metric.casts.toFixed(1);
					const landed = metric.landedHits || metric.casts;
					MetricsCombinedTooltipTable({
						tooltipElement: cellElem,
						groups: [
							{
								spellSchool: metric.spellSchool,
								totalPercentage: 100,
								data: [
									{ name: 'Hits', value: landed, percentage: 100 - metric.missPercent - metric.dodgePercent - metric.parryPercent - metric.blockPercent },
									{ name: 'Miss', value: metric.misses, percentage: metric.missPercent },
									{ name: 'Dodge', value: metric.dodges, percentage: metric.dodgePercent },
									{ name: 'Parry', value: metric.parries, percentage: metric.parryPercent },
									{ name: 'Block', value: metric.blocks, percentage: metric.blockPercent },
								],
							},
						],
					});
				},
			},
			{
				name: 'Avg Cast',
				tooltip: 'Damage / Attacks',
				getValue: (metric: ActionMetrics) => metric.avgCast,
				getDisplayString: (metric: ActionMetrics) => metric.avgCast.toFixed(1),
			},
			{
				name: 'Hits',
				tooltip: 'Hits + Crits + Glances + Blocks',
				getValue: (metric: ActionMetrics) => metric.landedHits,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => {
					cellElem.textContent = metric.landedHits.toFixed(1);
					const landed = metric.landedHits || 1;
					MetricsCombinedTooltipTable({
						tooltipElement: cellElem,
						groups: [
							{
								spellSchool: metric.spellSchool,
								totalPercentage: 100,
								data: [
									{ name: 'Hit', value: metric.hits, percentage: (metric.hits / landed) * 100 },
									{ name: 'Critical Hit', value: metric.crits, percentage: (metric.crits / landed) * 100 },
									{ name: 'Glancing Blow', value: metric.glances, percentage: (metric.glances / landed) * 100 },
									{ name: 'Blocked Hit', value: metric.blocks, percentage: (metric.blocks / landed) * 100 },
								],
							},
						],
					});
				},
			},
			{
				name: 'Avg Hit',
				tooltip: 'Damage / (Hits + Crits + Glances + Blocks)',
				getValue: (metric: ActionMetrics) => metric.avgHit,
				getDisplayString: (metric: ActionMetrics) => metric.avgHit.toFixed(1),
			},
			{
				name: 'Crit %',
				tooltip: 'Crits / Swings',
				getValue: (metric: ActionMetrics) => metric.critPercent,
				getDisplayString: (metric: ActionMetrics) => metric.critPercent.toFixed(2) + '%',
			},
			{
				name: 'Avoid %',
				tooltip: 'Misses + Dodges + Parries + Blocks / Swings',
				getValue: (metric: ActionMetrics) => metric.missPercent + metric.dodgePercent + metric.parryPercent + metric.blockPercent,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => {
					const avoided = metric.missPercent + metric.dodgePercent + metric.parryPercent + metric.blockPercent;
					cellElem.textContent = avoided.toFixed(2) + '%';
					MetricsCombinedTooltipTable({
						tooltipElement: cellElem,
						groups: [
							{
								spellSchool: metric.spellSchool,
								totalPercentage: 100,
								data: [
									{ name: 'Miss', value: metric.misses, percentage: metric.missPercent },
									{ name: 'Dodge', value: metric.dodges, percentage: metric.dodgePercent },
									{ name: 'Parry', value: metric.parries, percentage: metric.parryPercent },
									{ name: 'Block', value: metric.blocks, percentage: metric.blockPercent },
								],
							},
						],
					});
				},
			},
			{
				name: 'DPET',
				tooltip: 'Damage / Avg Cast Time',
				getValue: (metric: ActionMetrics) => metric.dpet,
				getDisplayString: (metric: ActionMetrics) => metric.dpet.toFixed(1),
			},
			{
				name: 'DPS',
				tooltip: 'Damage / Encounter Duration',
				headerCellClass: 'text-body',
				sort: ColumnSortType.Descending,
				getValue: (metric: ActionMetrics) => metric.dps,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => {
					const span = document.createElement('span');
					span.classList.add('text-success');
					span.textContent = metric.dps.toFixed(1);
					cellElem.appendChild(span);
				},
			},
		]);
	}

	getGroupedMetrics(resultData: SimResultData): Array<Array<ActionMetrics>> {
		const players = resultData.result.getPlayers(resultData.filter);
		if (players.length != 1) {
			return [];
		}

		const targets = resultData.result.getTargets(resultData.filter);
		// Combine melee + spell damage taken into a single list, grouped by action id.
		const targetActions = targets
			.flatMap(target => [...target.getMeleeActions(), ...target.getSpellActions()])
			.map(action => action.forTarget(resultData.filter));
		const actionGroups = ActionMetrics.groupById(targetActions);

		return actionGroups;
	}

	mergeMetrics(metrics: Array<ActionMetrics>): ActionMetrics {
		// TODO: Use NPC ID here instead of pet ID.
		return ActionMetrics.merge(metrics, true, metrics[0].unit?.petActionId || undefined);
	}
}
